package scp_candidate.Mining_Threat_Retreat_Supervisor

import org.sireum._
import art._
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Threat_Qualification_Api {
  def id: Art.BridgeId
  def raw_threat_Id : Art.PortId
  def qualified_threat_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualified_threat: Mining_Threat_Retreat_Supervisor.Threat_Observation = $

  def put_qualified_threat(value : Mining_Threat_Retreat_Supervisor.Threat_Observation) : Unit = {
    Contract(
      Modifies(qualified_threat),
      Ensures(
        qualified_threat == value
      )
    )
    Spec {
      qualified_threat = value
    }

    Art.putValue(qualified_threat_Id, Mining_Threat_Retreat_Supervisor.Threat_Observation_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Threat_Qualification_Initialization_Api (
  val id: Art.BridgeId,
  val raw_threat_Id : Art.PortId,
  val qualified_threat_Id : Art.PortId) extends Threat_Qualification_Api

@datatype class Threat_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val raw_threat_Id : Art.PortId,
  val qualified_threat_Id : Art.PortId) extends Threat_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var raw_threat: Mining_Threat_Retreat_Supervisor.Threat_Observation = $

  def get_raw_threat() : Option[Mining_Threat_Retreat_Supervisor.Threat_Observation] = {
    Contract(
      Ensures(
        Res == Some(raw_threat)
      )
    )
    val value : Option[Mining_Threat_Retreat_Supervisor.Threat_Observation] = Art.getValue(raw_threat_Id) match {
      case Some(Mining_Threat_Retreat_Supervisor.Threat_Observation_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port raw_threat.  Expecting 'Mining_Threat_Retreat_Supervisor.Threat_Observation_Payload' but received ${v}")
        None[Mining_Threat_Retreat_Supervisor.Threat_Observation]()
      case _ => None[Mining_Threat_Retreat_Supervisor.Threat_Observation]()
    }
    return value
  }
}
